model:
rachana: 1
sutra: design-round
version: 1
description: 
match: { kind: design-round, priority: 10 }
title: { pill: "Protein engineering · Design round", id: "$.ROUND_ID" }
strip:
  - { label: "Round id", bind: "$.ROUND_ID" }
  - { label: "Round", bind: "$.ROUND", fmt: "amount0" }
  - { label: "Method", bind: "$.METHOD" }
  - { label: "Best activity", bind: "$.BEST_ACTIVITY" }
  - { label: "Median activity", bind: "$.MEDIAN_ACTIVITY", emphasis: true }
panels:
  - id: record
    kind: kv
    title: "Design round"
    columns:
      - { label: "Round id", bind: "$.ROUND_ID" }
      - { label: "Protein", bind: "link($.PROTEIN, 'protein')" }
      - { label: "Round", bind: "$.ROUND", fmt: "amount0" }
      - { label: "Method", bind: "$.METHOD" }
      - { label: "Started", bind: "$.STARTED", fmt: "date" }
      - { label: "Designs", bind: "$.DESIGNS", fmt: "amount0" }
      - { label: "Best design", bind: "link($.BEST_DESIGN, 'design')" }
      - { label: "Best activity", bind: "$.BEST_ACTIVITY" }
      - { label: "Median activity", bind: "$.MEDIAN_ACTIVITY" }
      - { label: "Trapped", bind: "$.TRAPPED", fmt: "amount0" }
      - { label: "Note", bind: "$.NOTE" }
keys: { F9: "raw" }
